ALTER TABLE public.trips ADD COLUMN contractor_assigned_workspace_id uuid REFERENCES public.workspaces(id);
CREATE FUNCTION public.contractor_assignment_boundary() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_OP='INSERT' AND NEW.contractor_assigned_workspace_id IS NOT NULL OR TG_OP='UPDATE' AND NEW.contractor_assigned_workspace_id IS DISTINCT FROM OLD.contractor_assigned_workspace_id THEN IF coalesce(current_setting('app.contractor_assignment',true),'')<>'true' OR current_user NOT IN ('postgres','service_role') THEN RAISE EXCEPTION 'Controlled contractor assignment required';END IF;END IF;RETURN NEW;END $$;
CREATE TRIGGER contractor_assignment_boundary BEFORE INSERT OR UPDATE ON public.trips FOR EACH ROW EXECUTE FUNCTION public.contractor_assignment_boundary();
CREATE FUNCTION public.contractor_assign_trip(_trip uuid,_contractor uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE t public.trips;src uuid;target_user uuid;BEGIN SELECT * INTO t FROM public.trips WHERE id=_trip FOR UPDATE;IF t.id IS NULL OR t.status IN ('completed','canceled','cancelled','no_show') OR t.trip_kind<>'passenger' OR t.transport_type<>'ambulatory' OR t.network_provider_workspace_id IS NOT NULL THEN RAISE EXCEPTION 'Assignable owned ambulatory trip required';END IF;SELECT workspace_id INTO src FROM public.ride_requests WHERE id=t.ride_request_id;IF src IS NULL THEN SELECT m.workspace_id INTO src FROM public.workspace_members m JOIN public.workspaces w ON w.id=m.workspace_id WHERE m.user_id=t.created_by AND m.role='owner' AND m.removed_at IS NULL AND w.provider_subtype='nemt_business';END IF;IF NOT public.network_workspace_access(src,true) OR NOT EXISTS(SELECT 1 FROM public.workspace_members WHERE workspace_id=src AND user_id=auth.uid() AND role IN ('owner','admin') AND NOT is_contractor AND removed_at IS NULL) OR NOT public.contractor_connected(src,_contractor) OR NOT public.pass4p_service_eligible(_contractor,'ambulatory') THEN RAISE EXCEPTION 'Active connected eligible contractor and business manager required';END IF;SELECT user_id INTO target_user FROM public.workspace_members WHERE workspace_id=_contractor AND role='owner' AND NOT is_contractor AND removed_at IS NULL;IF target_user IS NULL THEN RAISE EXCEPTION 'Contractor owner unavailable';END IF;PERFORM set_config('app.contractor_assignment','true',true);UPDATE public.trips SET assigned_to=target_user,contractor_assigned_workspace_id=_contractor,driver_id=NULL,vehicle_id=NULL WHERE id=_trip;INSERT INTO public.trip_dispatch_events(trip_id,event_type,actor_id,details) VALUES(_trip,'contractor_assigned',auth.uid(),jsonb_build_object('contractor_workspace_id',_contractor,'source_workspace_id',src));END $$;
REVOKE ALL ON FUNCTION public.contractor_assign_trip(uuid,uuid) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.contractor_assign_trip(uuid,uuid) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.enforce_assigned_provider_is_approved() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE ws uuid;BEGIN IF NEW.assigned_to IS NULL OR (TG_OP='UPDATE' AND NEW.assigned_to IS NOT DISTINCT FROM OLD.assigned_to) THEN RETURN NEW;END IF;SELECT m.workspace_id INTO ws FROM public.workspace_members m JOIN public.workspaces w ON w.id=m.workspace_id WHERE m.user_id=NEW.assigned_to AND m.role='owner' AND m.removed_at IS NULL AND w.provider_subtype='independent_contractor';IF ws IS NOT NULL THEN IF NEW.transport_type<>'ambulatory' OR NOT public.pass4p_service_eligible(ws,'ambulatory') THEN RAISE EXCEPTION 'Eligible ambulatory contractor required';END IF;ELSIF NOT public.is_eligible_transport_provider(NEW.assigned_to) THEN RAISE EXCEPTION 'That account is not an approved transportation provider and cannot receive trips';END IF;RETURN NEW;END $$;
CREATE POLICY contractor_addressed_trip_read ON public.trips FOR SELECT TO authenticated USING(contractor_assigned_workspace_id IS NOT NULL AND public.network_workspace_access(contractor_assigned_workspace_id,true));
CREATE POLICY contractor_no_unrelated_trips ON public.trips AS RESTRICTIVE FOR SELECT TO authenticated USING(NOT EXISTS(SELECT 1 FROM public.workspace_members m JOIN public.workspaces w ON w.id=m.workspace_id WHERE m.user_id=auth.uid() AND m.role='owner' AND m.removed_at IS NULL AND w.provider_subtype='independent_contractor') OR created_by=auth.uid() OR assigned_to=auth.uid() OR public.network_workspace_access(contractor_assigned_workspace_id,true) OR (network_provider_workspace_id IS NOT NULL AND public.network_workspace_access(network_provider_workspace_id,true)) OR public.has_role(auth.uid(),'admin'));